INSERT INTO `display_announcements` (`id`, `title`, `text`, `order_index`, `is_active`, `created_at`, `updated_at`) VALUES
('1', 'Pengumuman Bebas Biaya Layanan Kependudukan', 'PERHATIAN KEPADA BAPAK/IBU SELURUH PENGUNJUNG MAL PELAYANAN PUBLIK KAB. DELI SERDANG. SEBAGAI INFORMASI, UNTUK SELURUH LAYANAN KEPENDUDUKAN PADA MAL PELAYANAN PUBLIK KAB. DELI SERDANG TIDAK DIPUNGUT BIAYA APAPUN. KAMI MENGHIMBAU KEPADA SELURUH PENGGUNA LAYANAN KEPENDUDUKAN AGAR LEBIH BERHATI-HATI TERHADAP OKNUM DILUAR PETUGAS RESMI PADA MAL PELAYANAN PUBLIK KAB. DELI SERDANG. ATAS KERJASAMANYA KAMI UCAPKAN TERIMA KASIH.', '1', '1', '2026-07-15 01:53:51', '2026-07-15 01:53:51'),
('2', 'Himbauan Pendamping & Kuota KTP IKD', 'KEPADA BAPAK/IBU PENDAMPING DIMOHON UNTUK MENUNGGU DILUAR GEDUNG. UNTUK LAYANAN PENCETAKAN KTP SETIAP HARINYA TERSEDIA 100 KEPING KTP DAN MASYARAKAT DIWAJIBKAN UNTUK MENGUNDUH APLIKASI IKD. SELAIN MAL PELAYANAN PUBLIK KAB. DELI SERDANG MASYARAKAT JUGA DAPAT MELAKUKAN PENGURUSAN ADMINISTRASI KEPENDUDUKAN PADA LAYANAN PATEN KALI YANG TERSEDIA DISELURUH KECAMATAN YANG BERADA DI KAB. DELI SERDANG. ATAS KERJASAMANYA KAMI UCAPKAN TERIMA KASIH.', '2', '1', '2026-07-15 01:53:51', '2026-07-15 01:53:51'),
('3', 'Himbauan Larangan Duduk di Lantai & Kebersihan', 'SELURUH PENGUNJUNG MAL PELAYANAN PUBLIK KAB. DELI SERDANG DILARANG UNTUK DUDUK DILANTAI, MEROKOK DAN MEMBAWA MAKANAN KE DALAM GEDUNG. PENGUNJUNG YANG TELAH SELESAI MENDAPATKAN LAYANAN DIHARAPKAN DAPAT MENINGGALKAN GEDUNG MAL PELAYANAN PUBLIK KAB. DELI SERDANG. BAGI PENGUNJUNG MAL PELAYANAN PUBLIK KABUPATEN DELI SERDANG YANG MEMBUTUHKAN INFORMASI DAPAT LANGSUNG KEBAGIAN INFORMASI. ATAS KERJASAMANYA KAMI UCAPKAN TERIMA KASIH.', '3', '1', '2026-07-15 01:53:51', '2026-07-15 01:53:51');
